# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def make(last: str, first: str) -> Student:
    return Student(last + first, last, first, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbot", "Cleo"),
        ]

    def test_sorted_and_grouped(self):
        lines = seat_rows(self.pupils, 2)
        self.assertEqual(lines, [
            "Row 1: Abbot, Cleo | Dunmere, Piet",
            "Row 2: Halloway, Juno",
        ])

    def test_single_row(self):
        lines = seat_rows(self.pupils, 10)
        self.assertEqual(len(lines), 1)

    def test_zero_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.pupils, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.pupils, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 2)
